[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Sales Invoice</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": "Accounting Dimensions"}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<html lang="en">
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Styled Table</title>
  <style>
    .invoice-container {
        font-size: 15px;
        font-family: 'Arial-MT', Arial, sans-serif;
        color: black;
      }

      .invoice-container * {
        font-size: inherit !important;
        font-family: 'Arial-MT', Arial, sans-serif !important;
        color: black;
      }
    table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed; /* Fix column width management */
    }

    td, th {
      border: 1px solid black;
      vertical-align: middle;
      padding: 6px;
    }

    .grand-total {
      text-align: right;
    }
    .invoice-title {
        font-size: 24px !important;
    }
    .invoice-head-line {
        font-size: 11px !important;
    }
    .item-1{
        font-size: 14px !important;
    }
    .irn-text
    {
        word-wrap: break-word; 
        white-space: normal;
        font-size: 11px;
        font-weight: bold !important;
    }


  </style>
<div class="invoice-container">
<table>
    <tr>
    <td colspan="24">
      <div style="display: flex; justify-content: space-between; align-items: center; margin:0;">
      <div style="width: 100%; text-align: center;">
        <p class="invoice-title"><b>
    {% if doc.is_return == 1 %}
      CREDIT NOTE
    {% else %}
      TAX INVOICE
    {% endif %}
  </b></p>

      </div>
        <div style="text-align: right; font-size: 12px; flex-shrink: 0;">
          <i>(Original for Recipient)</i>
        </div>
      </div>
      <p class="invoice-head-line">
        Registered Office: No 217/A, Near Metro Station Kalvari Temple Road, Miyapur, Hyderabad Telangana, State Code: 36, PIN Code: 500049 India, Contact no: 9666496664 & Email id: info@vbond.in, info@valuebond.in, accounts@valuebond.in
      </p>
    </td>
  </tr>

<tr class="third-row">
    <td rowspan="4" colspan="12">
      <div style="display: flex; justify-content: space-between; align-items: center; height: 120px;">
         <div style="flex: 1; text-align: left;">
          {% if logo_for_printing != "" %}
            <img src="{{ logo_for_printing }}" style="height: 130px; width: 130px; object-fit: contain;">
          {% endif %}
        </div>
        <div>
          <P> <b>{{doc.company}}</b><br>{{doc.company_address_display}}</P>
        </div>

        <!--<div style="flex: 1; text-align: right;">-->
        <!--    {% if doc.irn %}-->
        <!--      {% set e_invoice_log = frappe.db.get_value("e-Invoice Log", doc.irn,-->
        <!--        ("invoice_data", "signed_qr_code"), as_dict=True) %}-->
        <!--      <div style="display: inline-block; height: 125px; width: 125px;">-->
        <!--        <div style="transform: scale(0.7); transform-origin: top right;">-->
        <!--          {{ web_block('e-Invoice QR', values={'e_invoice_qr_text': e_invoice_log.signed_qr_code }) }}-->
        <!--        </div>-->
        <!--      </div>-->
        <!--    {% endif %}-->
        <!--</div>-->
      </div>

    </td>
    <!--<td colspan="12">IRN No<br><span class="irn-text">{{doc.irn or ""}}</span></td>-->
</tr>

<tr class="fourth-row">
    <td colspan="6">Inv. No<br><b>{{doc.name or ""}}</b></td>
    <td colspan="6">Dated<br><b>{{doc.posting_date or ""}}</b></td>
</tr>

{% if doc.irn %}
{% set e_invoice_log = frappe.db.get_value( "e-Invoice Log", doc.irn,
("invoice_data", "signed_qr_code"), as_dict=True ) %}

{% if e_invoice_log %}
{% set invoice_data = json.loads(e_invoice_log.invoice_data) %}
{% set date_format = frappe.db.get_single_value("System Settings",'date_format').replace("mm","MM")
%}
{% endif %}{% endif %}
<tr class="fourth-row">
    <td colspan="6">Ack No.<br><b>{{ invoice_data.get("AckNo") if doc.irn and invoice_data.get("AckNo")
		else '' }}</b></td>
    <td colspan="6">SO No.<br><b>{{doc.custom_so_no or ""}}</b></td>
</tr>
<tr class="fourth-row">
    <!--<p>IRN No:<b>{{doc.irn or ""}}</b></p>-->
    <td colspan="12">
    Ship To<br><b>{{doc.shipping_address_name or ""}}</b><br>{{doc.shipping_address or ""}}</td>
</tr>


<tr>
  <td rowspan="4" colspan="12">Bill To<br><b>{{doc.customer or ""}}</b><br>{{doc.address_display or ""}}</td>
</tr>
<tr class="fourth-row">
    <td colspan="6">e-Waybill No.<br><b>{{doc.ewaybill or ""}}</b></td>
    <td colspan="6">
    Delivery Note<br>
    {% set delivery_note_list = [] %}
    {% for item in doc.items %}
        {% if item.delivery_note and item.delivery_note not in delivery_note_list %}
            {% set _ = delivery_note_list.append(item.delivery_note) %}
        {% endif %}
    {% endfor %}
    <b>
    {{ delivery_note_list | join(', ') }}
    </b>
  </td>
</tr>
<tr class="fourth-row">
    <td colspan="6">Customer's Purchase Order<br><b>{{doc.po_no or ""}}</b></td>
    <td colspan="6">Destination<br><b>{{doc.custom_destination or ""}}</b></td>
</tr>
<tr class="fourth-row">
    <td colspan="6">Dispach From<br><b>{% if doc.company_address %}
        {% set company_address = frappe.get_doc("Address", doc.company_address) %}
        {{ company_address.city or "" }}
    {% endif %}</b></td>
    <td colspan="6">Vehicle No.<br><b>{{doc.vehicle_no or ""}}</b></td>
</tr>

<tr>
    <td><b>Sr.</b></td>
    <td colspan="8" style="text-align: center;"><b>Description of Goods</b></td>
    <td colspan="2" style="text-align: center;"><b>HSN</b></td>
    <td colspan="2" style="text-align: center;"><b>Qty</b></td>
    <td colspan="2" style="text-align: center;"><b>Rate <br> (incul. of tax)</b></td>
    <td colspan="2" style="text-align: center;"><b>Rate <br> (excul. of tax)</b></td>
    <td colspan="2" style="text-align: center;"><b>Disc (%)</b></td>
    <td colspan="2" style="text-align: center;"><b>Disc amt</b></td>
    <td colspan="3" style="text-align: center;"><b>Amount</b></td>
</tr>
</table>
</div>
</html>"}]
